INSERT INTO `categories` VALUES ('0c4a1e8b-6f2d-4a91-b3e7-1d5f8a2c9b04','qisas-al-anbiya','Qisas al-Anbiya','قصص الأنبياء','Stories of the Prophets drawn from the Quran, reliable tafsir, and Ibn Kathir’s Qisas al-Anbiya.','قصص الأنبياء مستمدة من القرآن والتفاسير الموثوقة وقصص الأنبياء لابن كثير.',1,'2026-09-28 11:24:43.240','2026-09-28 11:24:43.240'),('1a7b3c9e-4d2f-4e18-8c6a-2f9d0b5e7a13','seerah-shamail','Seerah & Shama\'il','السيرة والشمائل','The life and noble character of Prophet Muhammad ﷺ.','حياة النبي محمد ﷺ وشمائله الكريمة.',2,'2026-09-28 11:24:43.240','2026-09-28 11:24:43.240'),('2b8c4d0f-5e3a-4f29-9d7b-3a0e1c6f8b24','sahabah','Sahabah','الصحابة','Companions of the Prophet ﷺ, including twelve key figures.','صحابة النبي ﷺ، ومنهم اثنا عشر علماً من أعلامهم.',3,'2026-09-28 11:24:43.241','2026-09-28 11:24:43.241'),('3c9d5e1a-6f4b-402a-ae8c-4b1f2d7a9c35','gleanings','Narratives & Successors','آثار وتابعون','Short authentic accounts of the Tabi\'un, successors, and other righteous predecessors.','قبسات قصيرة موثقة من أخبار التابعين ومن بعدهم من السلف.',4,'2026-09-28 11:24:43.241','2026-09-28 11:24:43.241');
