INSERT INTO `figures` VALUES ('10a1b2c3-d4e5-4060-8071-111111110001','0c4a1e8b-6f2d-4a91-b3e7-1d5f8a2c9b04','adam','Adam','آدم','peace be upon him','عليه السلام',0,1,'The first human and prophet, taught the names and placed on earth as Allah’s vicegerent.','أول البشر والأنبياء، علّمه الله الأسماء وجعله خليفة في الأرض.','2026-09-28 11:24:43.242','2026-09-28 11:24:43.242'),('10a1b2c3-d4e5-4060-8071-111111110002','0c4a1e8b-6f2d-4a91-b3e7-1d5f8a2c9b04','idris','Idris','إدريس','peace be upon him','عليه السلام',0,2,'A truthful prophet raised to a high station; called people back to Adam’s religion and taught justice and charity.','نبي صدّيق رفعه الله مكاناً عليّاً، دعا الناس إلى دين آبائه وعلّمهم العدل والصدقة.','2026-09-28 11:24:43.243','2026-09-28 11:24:43.243'),('10a1b2c3-d4e5-4060-8071-111111110003','0c4a1e8b-6f2d-4a91-b3e7-1d5f8a2c9b04','nuh','Nuh','نوح','peace be upon him','عليه السلام',0,3,'Called his people to worship Allah alone for centuries; those who believed were saved in the Ark from the Flood.','دعا قومه إلى عبادة الله وحده قروناً، ونجّى الله المؤمنين معه في السفينة من الطوفان.','2026-09-28 11:24:43.243','2026-09-28 11:24:43.243'),('10a1b2c3-d4e5-4060-8071-111111110004','0c4a1e8b-6f2d-4a91-b3e7-1d5f8a2c9b04','hud','Hud','هود','peace be upon him','عليه السلام',0,4,'Sent to the powerful people of ‘Ad, who were arrogant builders; he called them to worship Allah alone.','أرسل إلى قوم عاد الأقوياء المتجبرين، فدعاهم إلى إفراد الله بالعبادة.','2026-09-28 11:24:43.243','2026-09-28 11:24:43.243'),('10a1b2c3-d4e5-4060-8071-111111110005','0c4a1e8b-6f2d-4a91-b3e7-1d5f8a2c9b04','salih','Salih','صالح','peace be upon him','عليه السلام',0,5,'Sent to Thamud after ‘Ad; called them to tawhid and warned them concerning the she-camel of Allah.','أرسل إلى ثمود بعد عاد، فدعاهم إلى التوحيد وحذّرهم في شأن ناقة الله.','2026-09-28 11:24:43.243','2026-09-28 11:24:43.243'),('10a1b2c3-d4e5-4060-8071-111111110007','0c4a1e8b-6f2d-4a91-b3e7-1d5f8a2c9b04','ismail','Isma‘il','إسماعيل','peace be upon him','عليه السلام',0,7,'Son of Ibrahim, left with his mother Hajar in the barren valley of Makkah; linked to Zamzam and the Ka‘bah.','ابن إبراهيم، تُرك مع أمه هاجر في وادٍ غير ذي زرع بمكة، وارتبط باسم زمزم والبيت.','2026-09-28 11:24:43.244','2026-09-28 11:24:43.244'),('10a1b2c3-d4e5-4060-8071-111111110008','0c4a1e8b-6f2d-4a91-b3e7-1d5f8a2c9b04','ishaq','Ishaq','إسحاق','peace be upon him','عليه السلام',0,8,'Son of Ibrahim, granted after glad tidings; father of Yaqub and a prophet in the line of guidance.','ابن إبراهيم بُشّر به بعد الكبر، أبو يعقوب ونبي في سلسلة الهداية.','2026-09-28 11:24:43.244','2026-09-28 11:24:43.244'),('10a1b2c3-d4e5-4060-8071-111111110009','0c4a1e8b-6f2d-4a91-b3e7-1d5f8a2c9b04','yaqub','Yaqub','يعقوب','peace be upon him','عليه السلام',0,9,'Also called Israel; favored with prophethood, father of the twelve tribes including Yusuf.','يُدعى إسرائيل، آتاه الله النبوة، وأبو الأسباط الاثني عشر ومنهم يوسف.','2026-09-28 11:24:43.244','2026-09-28 11:24:43.244'),('10a1b2c3-d4e5-4060-8071-111111110010','0c4a1e8b-6f2d-4a91-b3e7-1d5f8a2c9b04','lut','Lut','لوط','peace be upon him','عليه السلام',0,10,'Nephew of Ibrahim, sent to the people of Sodom to forbid their open immorality and call them to Allah.','ابن أخي إبراهيم، أرسل إلى أهل سدوم لينهاهم عن الفواحش ويدعوهم إلى الله.','2026-09-28 11:24:43.244','2026-09-28 11:24:43.244'),('10a1b2c3-d4e5-4060-8071-111111110011','0c4a1e8b-6f2d-4a91-b3e7-1d5f8a2c9b04','shuaib','Shu‘aib','شعيب','peace be upon him','عليه السلام',0,11,'Sent to Madyan; commanded worship of Allah alone and fair measure in trade, forbidding corruption.','أرسل إلى مدين، فأمرهم بعبادة الله وإيفاء الكيل والميزان ونهاهم عن الفساد.','2026-09-28 11:24:43.244','2026-09-28 11:24:43.244'),('10a1b2c3-d4e5-4060-8071-111111110012','0c4a1e8b-6f2d-4a91-b3e7-1d5f8a2c9b04','yusuf','Yusuf','يوسف','peace be upon him','عليه السلام',0,12,'Son of Yaqub; thrown into a well, sold into Egypt, then raised by Allah through patience and trust to authority.','ابن يعقوب؛ أُلقي في الجبّ ثم بيع بمصر، فرفعه الله بالصبر والتوكل إلى الملك.','2026-09-28 11:24:43.244','2026-09-28 11:24:43.244'),('10a1b2c3-d4e5-4060-8071-111111110013','0c4a1e8b-6f2d-4a91-b3e7-1d5f8a2c9b04','ayyub','Ayyub','أيوب','peace be upon him','عليه السلام',0,13,'Patient prophet stricken with severe trial in health and wealth; he turned to Allah and was restored.','نبيٌّ صابر ابتُلي في بدنه وماله، فأناب إلى الله فردّ عليه عافيته.','2026-09-28 11:24:43.244','2026-09-28 11:24:43.244'),('10a1b2c3-d4e5-4060-8071-111111110014','0c4a1e8b-6f2d-4a91-b3e7-1d5f8a2c9b04','dhul-kifl','Dhul-Kifl','ذو الكفل','peace be upon him','عليه السلام',0,14,'Mentioned among the patient and righteous; Ibn Kathir places him among the prophets of firm resolve in obedience.','ذُكر مع الصابرين والصالحين، وعدّه ابن كثير فيمن ثبتوا على طاعة الله.','2026-09-28 11:24:43.244','2026-09-28 11:24:43.244'),('10a1b2c3-d4e5-4060-8071-111111110015','0c4a1e8b-6f2d-4a91-b3e7-1d5f8a2c9b04','yunus','Yunus','يونس','peace be upon him','عليه السلام',0,15,'Left his people in anger, was swallowed by the whale, then called upon Allah in the darkness and was rescued.','غادر قومه مغاضباً فالتقمه الحوت، فنادى الله في الظلمات فنجّاه.','2026-09-28 11:24:43.244','2026-09-28 11:24:43.244'),('10a1b2c3-d4e5-4060-8071-111111110016','0c4a1e8b-6f2d-4a91-b3e7-1d5f8a2c9b04','musa','Musa','موسى','peace be upon him','عليه السلام',0,16,'Sent to Pharaoh with clear signs; led the Children of Israel and received the Torah.','أرسل إلى فرعون بالآيات، وأخرج بني إسرائيل وأنزلت عليه التوراة.','2026-09-28 11:24:43.244','2026-09-28 11:24:43.244'),('10a1b2c3-d4e5-4060-8071-111111110017','0c4a1e8b-6f2d-4a91-b3e7-1d5f8a2c9b04','harun','Harun','هارون','peace be upon him','عليه السلام',0,17,'Brother of Musa and a prophet who supported him in calling Pharaoh and guiding the Israelites.','أخو موسى ونبيّ أيّده في دعوة فرعون وهداية بني إسرائيل.','2026-09-28 11:24:43.245','2026-09-28 11:24:43.245'),('10a1b2c3-d4e5-4060-8071-111111110018','0c4a1e8b-6f2d-4a91-b3e7-1d5f8a2c9b04','hizqeel','Hizqeel','حزقيل','peace be upon him','عليه السلام',0,18,'Known as Ezekiel; Ibn Kathir recounts him among the prophets after Musa who revived hope for the Israelites.','يُعرف بحزقيال؛ ذكره ابن كثير فيمن بعث بعد موسى لإحياء رجاء بني إسرائيل.','2026-09-28 11:24:43.245','2026-09-28 11:24:43.245'),('10a1b2c3-d4e5-4060-8071-111111110019','0c4a1e8b-6f2d-4a91-b3e7-1d5f8a2c9b04','ilyas','Ilyas','إلياس','peace be upon him','عليه السلام',0,19,'Called his people away from idolatry; Ibn Kathir includes him among the prophets between Musa and the later messengers.','دعا قومه لترك الشرك، وعدّه ابن كثير في الأنبياء بين موسى ومن بعدهم.','2026-09-28 11:24:43.245','2026-09-28 11:24:43.245'),('10a1b2c3-d4e5-4060-8071-111111110020','0c4a1e8b-6f2d-4a91-b3e7-1d5f8a2c9b04','shammil','Shammil','شمويل','peace be upon him','عليه السلام',0,20,'Samuel; appointed when the Israelites asked for a king after defeat, and guided them under Allah’s command.','شمويل؛ بُعث حين طلب بنو إسرائيل ملكاً بعد الهزيمة، فهداهم بأمر الله.','2026-09-28 11:24:43.245','2026-09-28 11:24:43.245'),('10a1b2c3-d4e5-4060-8071-111111110021','0c4a1e8b-6f2d-4a91-b3e7-1d5f8a2c9b04','dawud','Dawud','داود','peace be upon him','عليه السلام',0,21,'Defeated Goliath, was given kingship and the Zabur, and judged with justice and beautiful remembrance of Allah.','هزم جالوت، وآتاه الله الملك والزبور، وقضى بالعدل وأكثر من ذكر الله.','2026-09-28 11:24:43.245','2026-09-28 11:24:43.245'),('10a1b2c3-d4e5-4060-8071-111111110022','0c4a1e8b-6f2d-4a91-b3e7-1d5f8a2c9b04','sulaiman','Sulaiman','سليمان','peace be upon him','عليه السلام',0,22,'Inherited Dawud’s prophethood; taught the speech of birds and given dominion over jinn, men, and the wind.','ورث نبوة داود، وعُلّم منطق الطير وسُخّر له الجنّ والإنس والريح.','2026-09-28 11:24:43.245','2026-09-28 11:24:43.245'),('10a1b2c3-d4e5-4060-8071-111111110023','0c4a1e8b-6f2d-4a91-b3e7-1d5f8a2c9b04','shia','Shi‘a','شعيا','peace be upon him','عليه السلام',0,23,'Isaiah; advised the righteous king of his time and, according to Ibn Kathir, foretold later messengers.','شعيا؛ نصح ملك زمانه الصالح، وذكر ابن كثير أنه بشّر بمن يأتي من الرسل.','2026-09-28 11:24:43.245','2026-09-28 11:24:43.245'),('10a1b2c3-d4e5-4060-8071-111111110024','0c4a1e8b-6f2d-4a91-b3e7-1d5f8a2c9b04','aramaya','Aramaya','أرميا','peace be upon him','عليه السلام',0,24,'Jeremiah; warned his people and lived through the trials of Jerusalem as related by Ibn Kathir.','أرميا؛ أنذر قومه وعاش محنة بيت المقدس كما روى ابن كثير.','2026-09-28 11:24:43.246','2026-09-28 11:24:43.246'),('10a1b2c3-d4e5-4060-8071-111111110025','0c4a1e8b-6f2d-4a91-b3e7-1d5f8a2c9b04','daniel','Daniel','دانيال','peace be upon him','عليه السلام',0,25,'Preserved by Allah when cast among lions; a righteous figure of the Babylonian captivity in Ibn Kathir’s accounts.','نجّاه الله إذ أُلقي إلى الأسود؛ من صلحاء سبي بابل في روايات ابن كثير.','2026-09-28 11:24:43.246','2026-09-28 11:24:43.246'),('10a1b2c3-d4e5-4060-8071-111111110026','0c4a1e8b-6f2d-4a91-b3e7-1d5f8a2c9b04','uzair','Uzair','عزير','peace be upon him','عليه السلام',0,26,'Ezra; the Quranic account of one who passed by ruined dwellings and whom Allah caused to die a hundred years then raised.','عزير؛ صاحب قصة من مرّ على قرية خاوية فأماته الله مائة عام ثم بعثه.','2026-09-28 11:24:43.246','2026-09-28 11:24:43.246'),('10a1b2c3-d4e5-4060-8071-111111110027','0c4a1e8b-6f2d-4a91-b3e7-1d5f8a2c9b04','zakariyah','Zakariyah','زكريا','peace be upon him','عليه السلام',0,27,'Elderly prophet who cared for Maryam and prayed for an heir; granted Yahya in his old age.','نبي طاعن في السن كفل مريم ودعا بالذرية، فوُهب يحيى على الكبر.','2026-09-28 11:24:43.246','2026-09-28 11:24:43.246'),('10a1b2c3-d4e5-4060-8071-111111110028','0c4a1e8b-6f2d-4a91-b3e7-1d5f8a2c9b04','yahya','Yahya','يحيى','peace be upon him','عليه السلام',0,28,'Son of Zakariyah; given wisdom as a child, devout and merciful, holding fast to the Scripture.','ابن زكريا؛ أوتي الحكم صبيّاً، وكان تقيّاً رحيماً آخذاً بالكتاب بقوة.','2026-09-28 11:24:43.246','2026-09-28 11:24:43.246'),('10a1b2c3-d4e5-4060-8071-111111110029','0c4a1e8b-6f2d-4a91-b3e7-1d5f8a2c9b04','isa','Isa','عيسى','peace be upon him','عليه السلام',0,29,'Son of Maryam, created by Allah’s word; a messenger supported with clear signs, not a son of God.','ابن مريم خلقه الله بكلمة منه، رسول مؤيّد بالآيات، وليس ابناً لله.','2026-09-28 11:24:43.246','2026-09-28 11:24:43.246'),('10a1b2c3-d4e5-4060-8071-111111111001','0c4a1e8b-6f2d-4a91-b3e7-1d5f8a2c9b04','ibrahim','Ibrahim','إبراهيم','peace be upon him','عليه السلام',0,6,'The Friend of Allah and father of the prophets, who broke the idols and called his people to pure tawhid.','خليل الله وأبو الأنبياء، كسّر الأصنام ودعا قومه إلى التوحيد الخالص.','2026-09-28 11:24:43.243','2026-09-28 11:24:43.243'),('10a1b2c3-d4e5-4060-8071-111111111002','1a7b3c9e-4d2f-4e18-8c6a-2f9d0b5e7a13','muhammad','Muhammad','محمد','peace and blessings of Allah be upon him','صلى الله عليه وسلم',0,1,'The Messenger of Allah, seal of the prophets.','رسول الله وخاتم النبيين.','2026-09-28 11:24:43.246','2026-09-28 11:24:43.246'),('10a1b2c3-d4e5-4060-8071-111111111101','2b8c4d0f-5e3a-4f29-9d7b-3a0e1c6f8b24','abu-bakr-as-siddiq','Abu Bakr as-Siddiq','أبو بكر الصديق','may Allah be pleased with him','رضي الله عنه',1,1,'The first caliph and the closest companion of the Prophet ﷺ.','أول الخلفاء الراشدين وأقرب أصحاب النبي ﷺ.','2026-09-28 11:24:43.247','2026-09-28 11:24:43.247'),('10a1b2c3-d4e5-4060-8071-111111111102','2b8c4d0f-5e3a-4f29-9d7b-3a0e1c6f8b24','umar-ibn-al-khattab','Umar ibn al-Khattab','عمر بن الخطاب','may Allah be pleased with him','رضي الله عنه',1,2,'The second caliph, known as Al-Faruq.','ثاني الخلفاء الراشدين، الملقّب بالفاروق.','2026-09-28 11:24:43.247','2026-09-28 11:24:43.247'),('10a1b2c3-d4e5-4060-8071-111111111103','2b8c4d0f-5e3a-4f29-9d7b-3a0e1c6f8b24','uthman-ibn-affan','Uthman ibn Affan','عثمان بن عفان','may Allah be pleased with him','رضي الله عنه',1,3,'The third caliph, known as Dhun-Nurayn.','ثالث الخلفاء الراشدين، الملقّب بذي النورين.','2026-09-28 11:24:43.247','2026-09-28 11:24:43.247'),('10a1b2c3-d4e5-4060-8071-111111111104','2b8c4d0f-5e3a-4f29-9d7b-3a0e1c6f8b24','ali-ibn-abi-talib','Ali ibn Abi Talib','علي بن أبي طالب','may Allah be pleased with him','رضي الله عنه',1,4,'The fourth caliph, cousin and son-in-law of the Prophet ﷺ.','رابع الخلفاء الراشدين، ابن عم النبي ﷺ وصهره.','2026-09-28 11:24:43.247','2026-09-28 11:24:43.247'),('10a1b2c3-d4e5-4060-8071-111111111105','2b8c4d0f-5e3a-4f29-9d7b-3a0e1c6f8b24','talhah-ibn-ubaydullah','Talhah ibn Ubaydullah','طلحة بن عبيد الله','may Allah be pleased with him','رضي الله عنه',1,5,'Among the ten promised Paradise; known as Talhah the Generous.','من العشرة المبشرين بالجنة، يُعرف بطلحة الفيّاض.','2026-09-28 11:24:43.247','2026-09-28 11:24:43.247'),('10a1b2c3-d4e5-4060-8071-111111111106','2b8c4d0f-5e3a-4f29-9d7b-3a0e1c6f8b24','az-zubayr-ibn-al-awwam','Az-Zubayr ibn al-Awwam','الزبير بن العوام','may Allah be pleased with him','رضي الله عنه',1,6,'Among the ten promised Paradise; hawari of the Messenger of Allah ﷺ.','من العشرة المبشرين بالجنة، حواري رسول الله ﷺ.','2026-09-28 11:24:43.247','2026-09-28 11:24:43.247'),('10a1b2c3-d4e5-4060-8071-111111111107','2b8c4d0f-5e3a-4f29-9d7b-3a0e1c6f8b24','abd-al-rahman-ibn-awf','Abd al-Rahman ibn Awf','عبد الرحمن بن عوف','may Allah be pleased with him','رضي الله عنه',1,7,'Among the ten promised Paradise; a trusted merchant and early emigrant.','من العشرة المبشرين بالجنة، تاجر أمين من السابقين المهاجرين.','2026-09-28 11:24:43.247','2026-09-28 11:24:43.247'),('10a1b2c3-d4e5-4060-8071-111111111108','2b8c4d0f-5e3a-4f29-9d7b-3a0e1c6f8b24','sad-ibn-abi-waqqas','Sa\'d ibn Abi Waqqas','سعد بن أبي وقاص','may Allah be pleased with him','رضي الله عنه',1,8,'Among the ten promised Paradise; the first to shoot an arrow in the path of Allah.','من العشرة المبشرين بالجنة، أول من رمى بسهم في سبيل الله.','2026-09-28 11:24:43.248','2026-09-28 11:24:43.248'),('10a1b2c3-d4e5-4060-8071-111111111109','2b8c4d0f-5e3a-4f29-9d7b-3a0e1c6f8b24','said-ibn-zayd','Sa\'id ibn Zayd','سعيد بن زيد','may Allah be pleased with him','رضي الله عنه',1,9,'Among the ten promised Paradise; an early convert from the Quraysh.','من العشرة المبشرين بالجنة، من السابقين إلى الإسلام من قريش.','2026-09-28 11:24:43.248','2026-09-28 11:24:43.248'),('10a1b2c3-d4e5-4060-8071-111111111110','2b8c4d0f-5e3a-4f29-9d7b-3a0e1c6f8b24','abu-ubaydah-ibn-al-jarrah','Abu Ubaydah ibn al-Jarrah','أبو عبيدة بن الجراح','may Allah be pleased with him','رضي الله عنه',1,10,'Among the ten promised Paradise; Amin of this Ummah.','من العشرة المبشرين بالجنة، أمين هذه الأمة.','2026-09-28 11:24:43.249','2026-09-28 11:24:43.249'),('10a1b2c3-d4e5-4060-8071-111111111111','2b8c4d0f-5e3a-4f29-9d7b-3a0e1c6f8b24','khadijah-bint-khuwaylid','Khadijah bint Khuwaylid','خديجة بنت خويلد','may Allah be pleased with her','رضي الله عنها',1,11,'First wife of the Prophet ﷺ and the first to believe in his message.','زوج النبي ﷺ الأولى وأول من آمن برسالته.','2026-09-28 11:24:43.249','2026-09-28 11:24:43.249'),('10a1b2c3-d4e5-4060-8071-111111111112','2b8c4d0f-5e3a-4f29-9d7b-3a0e1c6f8b24','aishah-bint-abi-bakr','Aishah bint Abi Bakr','عائشة بنت أبي بكر','may Allah be pleased with her','رضي الله عنها',1,12,'Mother of the Believers and a foremost narrator of the Sunnah.','أم المؤمنين ومن أعلم رواة السنة.','2026-09-28 11:24:43.249','2026-09-28 11:24:43.249'),('10a1b2c3-d4e5-4060-8071-111111111201','3c9d5e1a-6f4b-402a-ae8c-4b1f2d7a9c35','uways-al-qarni','Uways al-Qarni','أويس القرني','may Allah have mercy on him','رحمه الله',0,1,'A Tabi\'i from Yemen, praised by the Prophet ﷺ for his devotion to his mother.','تابعي من اليمن، أثنى عليه النبي ﷺ لبرّه بوالدته.','2026-09-28 11:24:43.249','2026-09-28 11:24:43.249');
