-- Table structure for table `stories`
--

DROP TABLE IF EXISTS `stories`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `stories` (
  `id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `category_id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `figure_id` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `slug` varchar(160) COLLATE utf8mb4_unicode_ci NOT NULL,
  `title_en` varchar(512) COLLATE utf8mb4_unicode_ci NOT NULL,
  `title_ar` varchar(512) COLLATE utf8mb4_unicode_ci NOT NULL,
  `summary_en` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `content_en` mediumtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `content_ar` mediumtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `authenticity_grade` enum('sahih','hasan','athar','historical') COLLATE utf8mb4_unicode_ci NOT NULL,
  `publication_status` enum('draft','in_review','approved','published','archived') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft',
  `reviewer_id` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `reviewed_at` datetime(3) DEFAULT NULL,
  `published_at` datetime(3) DEFAULT NULL,
  `audio_url` text COLLATE utf8mb4_unicode_ci,
  `artwork_url` text COLLATE utf8mb4_unicode_ci,
  `audio` json DEFAULT NULL,
  `timed_cues` json NOT NULL,
  `revision` int NOT NULL DEFAULT '1',
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_stories_slug` (`slug`),
  KEY `idx_stories_catalog` (`publication_status`,`category_id`,`published_at`),
  KEY `idx_stories_figure` (`figure_id`),
  KEY `idx_stories_authenticity` (`authenticity_grade`),
  KEY `fk_stories_category` (`category_id`),
  KEY `fk_stories_reviewer` (`reviewer_id`),
  CONSTRAINT `fk_stories_category` FOREIGN KEY (`category_id`) REFERENCES `categories` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `fk_stories_figure` FOREIGN KEY (`figure_id`) REFERENCES `figures` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_stories_reviewer` FOREIGN KEY (`reviewer_id`) REFERENCES `profiles` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `stories_publication_review_check` CHECK (((`publication_status` not in (_utf8mb4'approved',_utf8mb4'published')) or ((`reviewer_id` is not null) and (`reviewed_at` is not null))))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

